_PRODUCT_EXCLUDE = (":(exclude).harness", ":(exclude).harness/**")


def _untracked_paths(repo_root: Path) -> set[str]:
    paths = set()
    for name in (
        _run(repo_root, "ls-files", "--others", "--exclude-standard")
        .decode()
        .splitlines()
    ):
        candidate = Path(name)
        # Git owns discovery. Avoid a pre-scope Path.is_file metadata probe;
        # later scoped reads bind actual file content and fail closed on races.
        if (
            name
            and not candidate.is_absolute()
            and ".." not in candidate.parts
            and not (name == ".harness" or name.startswith(".harness/"))
        ):
            paths.add(name)
    return paths


def _working_paths(repo_root: Path) -> set[str]:
    paths = set()
    for args in (
        ("diff", "--name-only", "HEAD", "--", ".", *_PRODUCT_EXCLUDE),
        ("diff", "--cached", "--name-only", "HEAD", "--", ".", *_PRODUCT_EXCLUDE),
    ):
        paths.update(
            name for name in _run(repo_root, *args).decode().splitlines() if name
        )
    return paths | _untracked_paths(repo_root)


def _fingerprint(repo_root: Path) -> str:
    """Product workspace fingerprint; control-plane files are excluded."""
    parts = [
        _run(repo_root, "rev-parse", "HEAD"),
        _run(repo_root, "diff", "--binary", "HEAD", "--", ".", *_PRODUCT_EXCLUDE),
        _run(
            repo_root,
            "diff",
            "--cached",
            "--binary",
            "HEAD",
            "--",
            ".",
            *_PRODUCT_EXCLUDE,
        ),
    ]
    from harness.source_access import _package_open

    for name in sorted(_untracked_paths(repo_root)):
        path = repo_root / name
        with _package_open(path):
            parts.extend([name.encode(), hashlib.sha256(path.read_bytes()).digest()])
    return "sha256:" + hashlib.sha256(b"\0".join(parts)).hexdigest()

def _projection(
    record,
    *,
    current_head,
    current_workspace,
    expected_success,
    require_current_workspace=True,
) -> EvidenceProjection:
    try:
        validate(record, read_schema("evidence.schema.json"))
    except (OSError, json.JSONDecodeError, ValidationError):
        return EvidenceProjection(
            EvidenceStatus.INVALID,
            "EVIDENCE_SCHEMA_INVALID",
            record if isinstance(record, dict) else None,
            None,
            current_workspace,
        )
    if record.get("commit") != current_head:
        return EvidenceProjection(
            EvidenceStatus.STALE,
            "EVIDENCE_HEAD_MISMATCH",
            record,
            record.get("workspace_fingerprint"),
            current_workspace,
        )
    before = record.get("workspace_fingerprint")
    after = record.get("workspace_fingerprint_after")
    if before != after or (
        require_current_workspace
        and (before != current_workspace or after != current_workspace)
    ):
        return EvidenceProjection(
            EvidenceStatus.STALE,
            "EVIDENCE_WORKSPACE_STALE",
            record,

def cmd_impact(action, value=None, reason=None, args=None):
    import yaml

    path, document = _impact()
    impact = document["impact"]
    if action == "show":
        print(yaml.safe_dump(document, sort_keys=False))
        return 0
    harness_dir = Path(".harness")
    task = load_task(harness_dir)
    if "scope" not in task:
        task["scope"] = {
            "owned_paths": list(impact.get("changed", [])),
            "protected_user_paths": [],
        }
        save_task(harness_dir, task)
    scope = task["scope"]
    if action == "scope":
        effective = workspace.project_task_scope(
            task,
            impact,
            inspected_paths=workspace.observability_inspected_paths(harness_dir),
        )
        print(
            yaml.safe_dump(
                {
                    "owned_paths": scope.get("owned_paths", []),
                    "protected_user_paths": scope.get("protected_user_paths", []),
                    "effective_scope": list(effective),
                },
                sort_keys=False,
            )
        )
        return 0
    if action in {"adopt-path", "ignore-user-path"}:
        owned, protected = scope["owned_paths"], scope["protected_user_paths"]
        if action == "adopt-path":
            user_changes = (task.get("risk") or {}).get("user_changes", {})
            paths = list(user_changes.get("paths", []))
            if value in paths:
                if (
                    "path_fingerprints" not in user_changes
                    and workspace.protected_user_changes_fingerprint(user_changes)
                    != user_changes.get("fingerprint")
                ):
                    print("USER_CHANGE_BASELINE_STALE", file=sys.stderr)
                    return 1
                if "path_fingerprints" not in user_changes:
                    user_changes["version"] = 2
                    user_changes["path_fingerprints"] = workspace.protected_path_fingerprints(
                        tuple(paths)
                    )
                user_changes["paths"] = [path for path in paths if path != value]
                user_changes["path_fingerprints"].pop(value, None)
                user_changes["fingerprint"] = workspace.aggregate_protected_path_fingerprints(
                    user_changes["path_fingerprints"]
                )
            if value not in owned:
                owned.append(value)
            if value in protected:
                protected.remove(value)
        elif value in owned or value in {item["ref"] for item in typed_contracts(impact)}:
            print("PROTECTED_PATH_OWNED", file=sys.stderr)
            return 1
        elif value not in protected:
            protected.append(value)
        save_task(harness_dir, task)
        return 0
    if action == "add-interface":
        if (
            task.get("risk", {}).get("profile") == "FAST"
            and args.visibility == "external"
        ):
            print("PUBLIC_INTERFACE_RISK_ESCALATION_REQUIRED", file=sys.stderr)
            return 1
        impact.setdefault("interfaces", []).append(
            {
                "id": value,
                "kind": args.kind,
                "visibility": args.visibility,
                "consumers": args.consumer,
                "compatibility": args.compatibility,
                "affected_contracts": [],
                "contract_id": args.contract_id,
            }
        )
        transaction.atomic_write(
            path, yaml.safe_dump(document, sort_keys=False).encode()
        )
        return 0
    key = {
        "add-change": "changed",
        "add-test": "required_tests",
        "add-dependent": "direct_dependents",
        "add-contract": "contracts",
        "add-risk": "risks",
    }.get(action)
    if key:
        if action == "add-contract":
            if value not in {item["ref"] for item in typed_contracts(impact)}:
                impact[key].append({"ref": value, "kind": args.kind})
        elif value not in impact[key]:
            impact[key].append(value)
        if action == "add-change":
            if value not in scope["owned_paths"]:
                scope["owned_paths"].append(value)
            if value in scope["protected_user_paths"]:
                scope["protected_user_paths"].remove(value)
            save_task(harness_dir, task)
    transaction.atomic_write(path, yaml.safe_dump(document, sort_keys=False).encode())
    return 0
